30	static JSValue js_arg_or_prop(JSContext *ctx, int argc, JSValueConst *argv,
31	                              int idx, const char *prop)
32	{
33	  if (argc > 0 && JS_IsObject(argv[0]) && !JS_IsArray(ctx, argv[0]))
34	    {
35	      return JS_GetPropertyStr(ctx, argv[0], prop);
36	    }
37	
38	  if (argc > idx && JS_IsObject(argv[idx]) && !JS_IsArray(ctx, argv[idx]))
39	    {
40	      return JS_GetPropertyStr(ctx, argv[idx], prop);
41	    }
42	
43	  if (argc > idx)
44	    {
45	      return JS_DupValue(ctx, argv[idx]);
46	    }
47	
48	  return JS_UNDEFINED;
49	}
