51	static int js_get_i32(JSContext *ctx, int argc, JSValueConst *argv,
52	                      int idx, const char *prop, int *out, int optional)
53	{
54	  JSValue v;
55	  int ret;
56	
57	  v = js_arg_or_prop(ctx, argc, argv, idx, prop);
58	  if (JS_IsUndefined(v) || JS_IsNull(v))
59	    {
60	      JS_FreeValue(ctx, v);
61	      if (optional)
62	        {
63	          return 1;
64	        }
65	
66	      JS_ThrowTypeError(ctx, "missing argument %s", prop);
67	      return -1;
68	    }
69	
70	  ret = JS_ToInt32(ctx, out, v);
71	  JS_FreeValue(ctx, v);
72	  return ret;
73	}
