140	static int js_to_bytes(JSContext *ctx, JSValueConst val,
141	                       uint8_t **out, size_t *len)
142	{
143	  uint8_t *buf;
144	  size_t n;
145	  uint8_t *ab;
146	  int64_t alen;
147	  uint32_t i;
148	  JSValue lenv;
149	
150	  *out = NULL;
151	  *len = 0;
152	
153	  if (JS_IsString(val))
154	    {
155	      const char *s = JS_ToCStringLen(ctx, &n, val);
156	      if (!s)
157	        {
158	          return -1;
159	        }
160	
161	      buf = js_malloc(ctx, n);
162	      if (!buf)
163	        {
164	          JS_FreeCString(ctx, s);
165	          return -1;
166	        }
167	
168	      memcpy(buf, s, n);
169	      JS_FreeCString(ctx, s);
170	      *out = buf;
171	      *len = n;
172	      return 0;
173	    }
174	
175	  ab = JS_GetArrayBuffer(ctx, &n, val);
176	  if (ab)
177	    {
178	      buf = js_malloc(ctx, n);
179	      if (!buf)
180	        {
181	          return -1;
182	        }
183	
184	      memcpy(buf, ab, n);
185	      *out = buf;
186	      *len = n;
187	      return 0;
188	    }
189	
190	  if (!JS_IsArray(ctx, val))
191	    {
192	      JS_ThrowTypeError(ctx, "expected array/string/arraybuffer");
193	      return -1;
194	    }
195	
196	  lenv = JS_GetPropertyStr(ctx, val, "length");
197	  if (JS_ToInt64(ctx, &alen, lenv))
198	    {
199	      JS_FreeValue(ctx, lenv);
200	      return -1;
201	    }
202	
203	  JS_FreeValue(ctx, lenv);
204	  if (alen < 0)
205	    {
206	      alen = 0;
207	    }
208	
209	  buf = js_malloc(ctx, (size_t)alen);
210	  if (!buf)
211	    {
212	      return -1;
213	    }
214	
215	  for (i = 0; i < (uint32_t)alen; i++)
216	    {
217	      JSValue el = JS_GetPropertyUint32(ctx, val, i);
218	      int32_t b;
219	
220	      if (JS_ToInt32(ctx, &b, el))
221	        {
222	          JS_FreeValue(ctx, el);
223	          js_free(ctx, buf);
224	          return -1;
225	        }
226	
227	      JS_FreeValue(ctx, el);
228	      buf[i] = (uint8_t)b;
229	    }
230	
231	  *out = buf;
232	  *len = (size_t)alen;
233	  return 0;
234	}
