236	static JSValue js_bytes_to_array(JSContext *ctx, const uint8_t *data,
237	                                 size_t len)
238	{
239	  JSValue arr;
240	  size_t i;
241	
242	  arr = JS_NewArray(ctx);
243	  for (i = 0; i < len; i++)
244	    {
245	      JS_SetPropertyUint32(ctx, arr, (uint32_t)i,
246	                           JS_NewInt32(ctx, data[i]));
247	    }
248	
249	  return arr;
250	}
