252	static int js_gpio_mode_from_str(const char *s)
253	{
254	  if (!s || !s[0])
255	    {
256	      return QJS_HW_GPIO_OUT;
257	    }
258	
259	  if (!strcmp(s, "out") || !strcmp(s, "output") || !strcmp(s, "out_pp"))
260	    {
261	      return QJS_HW_GPIO_OUT;
262	    }
263	
264	  if (!strcmp(s, "od") || !strcmp(s, "opendrain"))
265	    {
266	      return QJS_HW_GPIO_OD;
267	    }
268	
269	  if (!strcmp(s, "in_up") || !strcmp(s, "input_pullup") ||
270	      !strcmp(s, "up"))
271	    {
272	      return QJS_HW_GPIO_IN_UP;
273	    }
274	
275	  if (!strcmp(s, "in_down") || !strcmp(s, "input_pulldown") ||
276	      !strcmp(s, "down"))
277	    {
278	      return QJS_HW_GPIO_IN_DOWN;
279	    }
280	
281	  return QJS_HW_GPIO_IN;
282	}
