288	static JSValue js_gpio_pinmode(JSContext *ctx, JSValueConst this_val,
289	                               int argc, JSValueConst *argv)
290	{
291	  int pin = 0;
292	  int force = 0;
293	  int mode = QJS_HW_GPIO_OUT;
294	  int ret;
295	  char dir[24];
296	
297	  (void)(this_val);
298	  if (js_get_i32(ctx, argc, argv, 0, "gpio", &pin, 1) != 0 &&
299	      js_get_i32(ctx, argc, argv, 0, "pin", &pin, 0) != 0)
300	    {
301	      return JS_EXCEPTION;
302	    }
303	
304	  if (js_get_cstr(ctx, argc, argv, 1, "dir", dir, sizeof(dir)) == 0 ||
305	      js_get_cstr(ctx, argc, argv, 1, "direction", dir, sizeof(dir)) == 0 ||
306	      js_get_cstr(ctx, argc, argv, 1, "mode", dir, sizeof(dir)) == 0)
307	    {
308	      mode = js_gpio_mode_from_str(dir);
309	    }
310	  else
311	    {
312	      int m = 0;
313	
314	      if (js_get_i32(ctx, argc, argv, 1, "mode", &m, 1) == 0)
315	        {
316	          mode = m;
317	        }
318	    }
319	
320	  js_get_bool(ctx, argc, argv, 2, "force", &force);
321	  ret = qjs_hw_gpio_mode(pin, mode, force);
322	  if (ret < 0)
323	    {
324	      return js_hw_throw(ctx, ret);
325	    }
326	
327	  return JS_UNDEFINED;
328	}
