419	/****************************************************************************
420	 * WS2812
421	 ****************************************************************************/
422	
423	static int js_rgb_collect(JSContext *ctx, JSValueConst val,
424	                          uint8_t *out, size_t *nout)
425	{
426	  int64_t alen = 0;
427	  JSValue lenv;
428	  uint32_t i;
429	  uint32_t n = 0;
430	
431	  if (!JS_IsArray(ctx, val))
432	    {
433	      JS_ThrowTypeError(ctx, "rgb: expected [r,g,b] or [[r,g,b],...]");
434	      return -1;
435	    }
436	
437	  lenv = JS_GetPropertyStr(ctx, val, "length");
438	  if (JS_ToInt64(ctx, &alen, lenv))
439	    {
440	      JS_FreeValue(ctx, lenv);
441	      return -1;
442	    }
443	
444	  JS_FreeValue(ctx, lenv);
445	  if (alen <= 0)
446	    {
447	      *nout = 0;
448	      return 0;
449	    }
450	
451	  {
452	    JSValue first = JS_GetPropertyUint32(ctx, val, 0);
453	    int nested = JS_IsArray(ctx, first);
454	
455	    JS_FreeValue(ctx, first);
456	    if (nested)
457	      {
458	        if (alen > QJS_HW_WS2812_MAX)
459	          {
460	            JS_ThrowRangeError(ctx, "rgb: at most %d leds", QJS_HW_WS2812_MAX);
461	            return -1;
462	          }
463	
464	        for (i = 0; i < (uint32_t)alen; i++)
465	          {
466	            JSValue led = JS_GetPropertyUint32(ctx, val, i);
467	            int32_t r = 0;
468	            int32_t g = 0;
469	            int32_t b = 0;
470	            JSValue vr;
471	            JSValue vg;
472	            JSValue vb;
473	
474	            if (!JS_IsArray(ctx, led))
475	              {
476	                JS_FreeValue(ctx, led);
477	                JS_ThrowTypeError(ctx, "rgb: pixel must be [r,g,b]");
478	                return -1;
479	              }
480	
481	            vr = JS_GetPropertyUint32(ctx, led, 0);
482	            vg = JS_GetPropertyUint32(ctx, led, 1);
483	            vb = JS_GetPropertyUint32(ctx, led, 2);
484	            JS_ToInt32(ctx, &r, vr);
485	            JS_ToInt32(ctx, &g, vg);
486	            JS_ToInt32(ctx, &b, vb);
487	            JS_FreeValue(ctx, vr);
488	            JS_FreeValue(ctx, vg);
489	            JS_FreeValue(ctx, vb);
490	            JS_FreeValue(ctx, led);
491	            out[n++] = (uint8_t)r;
492	            out[n++] = (uint8_t)g;
493	            out[n++] = (uint8_t)b;
494	          }
495	      }
496	    else
497	      {
498	        if ((alen % 3) != 0 || alen > QJS_HW_WS2812_MAX * 3)
499	          {
500	            JS_ThrowTypeError(ctx, "rgb: flat array must be R,G,B,...");
501	            return -1;
502	          }
503	
504	        for (i = 0; i < (uint32_t)alen; i++)
505	          {
506	            JSValue el = JS_GetPropertyUint32(ctx, val, i);
507	            int32_t b = 0;
508	
509	            if (JS_ToInt32(ctx, &b, el))
510	              {
511	                JS_FreeValue(ctx, el);
512	                return -1;
513	              }
514	
515	            JS_FreeValue(ctx, el);
516	            out[n++] = (uint8_t)b;
517	          }
518	      }
519	  }
520	
521	  *nout = n;
522	  return 0;
523	}
