525	static JSValue js_rgb_write(JSContext *ctx, JSValueConst this_val,
526	                            int argc, JSValueConst *argv)
527	{
528	  int pin = QJS_HW_RGB_PIN;
529	  int r = 0;
530	  int g = 0;
531	  int b = 0;
532	  uint8_t pix[3];
533	  int ret;
534	
535	  (void)(this_val);
536	  if (argc > 0 && JS_IsObject(argv[0]) && !JS_IsArray(ctx, argv[0]))
537	    {
538	      if (js_get_i32(ctx, argc, argv, 0, "pin", &pin, 1) != 0 &&
539	          js_get_i32(ctx, argc, argv, 0, "gpio", &pin, 1) != 0)
540	        {
541	          pin = QJS_HW_RGB_PIN;
542	        }
543	
544	      js_get_i32(ctx, argc, argv, 0, "r", &r, 1);
545	      js_get_i32(ctx, argc, argv, 0, "g", &g, 1);
546	      js_get_i32(ctx, argc, argv, 0, "b", &b, 1);
547	    }
548	  else
549	    {
550	      if (argc >= 1)
551	        {
552	          JS_ToInt32(ctx, &pin, argv[0]);
553	        }
554	
555	      if (argc >= 4)
556	        {
557	          JS_ToInt32(ctx, &r, argv[1]);
558	          JS_ToInt32(ctx, &g, argv[2]);
559	          JS_ToInt32(ctx, &b, argv[3]);
560	        }
561	      else if (argc >= 2 && JS_IsArray(ctx, argv[1]))
562	        {
563	          size_t n = 0;
564	          uint8_t buf[QJS_HW_WS2812_MAX * 3];
565	
566	          if (js_rgb_collect(ctx, argv[1], buf, &n) < 0)
567	            {
568	              return JS_EXCEPTION;
569	            }
570	
571	          ret = qjs_hw_ws2812_write(pin, buf, n);
572	          if (ret < 0)
573	            {
574	              return js_hw_throw(ctx, ret);
575	            }
576	
577	          return JS_UNDEFINED;
578	        }
