113	
114	int qjs_hw_gpio_valid(int pin)
115	{
116	  return pin <= 21 || (pin >= 26 && pin < QJS_HW_NPINS);
117	}
118	
119	int qjs_hw_gpio_reserved(int pin, int force)
120	{
121	  if (!qjs_hw_gpio_valid(pin))
122	    {
123	      return -EINVAL;
124	    }
125	
126	  /* Octal PSRAM + flash on N16R8 occupy GPIO26-37. USB occupies 19/20. */
127	
128	  if (pin >= 26 && pin <= 37)
129	    {
130	      return -EPERM;
131	    }
132	
133	  if ((pin == 19 || pin == 20) && !force)
134	    {
135	      return -EPERM;
136	    }
137	
138	#ifdef CONFIG_QJS_HW_SAFE_PINS
139	  if (!force)
140	    {
141	      /* LCD moved to GPIO38-42. 43/44 stay UART0. 48 is WS2812. */
142	
143	      if ((pin >= 38 && pin <= 42) || pin == 43 || pin == 44)
144	        {
145	          return -EPERM;
146	        }
147	    }
148	#else
149	  (void)(force);
150	#endif
151	
152	  return OK;
153	}
154	
155	int qjs_hw_gpio_mode(int pin, int mode, int force)
156	{
157	  uint16_t attr;
158	  int ret;
159	
160	  ret = qjs_hw_gpio_reserved(pin, force);
161	  if (ret < 0)
162	    {
163	      return ret;
164	    }
165	
166	  switch (mode)
167	    {
168	      case QJS_HW_GPIO_OUT:
169	        attr = QJS_HW_OUTPUT_FUNCTION_2 | QJS_HW_INPUT_FUNCTION_2;
170	        break;
171	
172	      case QJS_HW_GPIO_OD:
173	        attr = QJS_HW_OUTPUT_FUNCTION_2 | QJS_HW_OPEN_DRAIN |
174	               QJS_HW_INPUT_FUNCTION_2;
175	        break;
176	
177	      case QJS_HW_GPIO_IN_DOWN:
178	        attr = QJS_HW_INPUT_FUNCTION_2 | QJS_HW_PULLDOWN;
179	        break;
180	
181	      case QJS_HW_GPIO_IN_UP:
182	        attr = QJS_HW_INPUT_FUNCTION_2 | QJS_HW_PULLUP;
183	        break;
184	
185	      case QJS_HW_GPIO_IN:
186	      default:
187	        attr = QJS_HW_INPUT_FUNCTION_2;
188	        break;
189	    }
190	
191	  if (mode == QJS_HW_GPIO_OUT || mode == QJS_HW_GPIO_OD)
192	    {
193	      esp32s3_gpio_matrix_out((uint32_t)pin, QJS_HW_SIG_GPIO_OUT_IDX,
194	                              false, false);
195	    }
196	
197	  ret = esp32s3_configgpio((uint32_t)pin, attr);
198	  if (ret < 0)
199	    {
200	      return ret;
201	    }
202	
203	  g_gpio_mode[pin] = (uint8_t)mode;
204	  return OK;
205	}
206	
207	int qjs_hw_gpio_write(int pin, int value)
208	{
209	  if (!qjs_hw_gpio_valid(pin))
210	    {
211	      return -EINVAL;
212	    }
213	
214	  esp32s3_gpiowrite(pin, value != 0);
215	  g_gpio_level[pin] = value != 0;
216	  return OK;
217	}
218	
219	int qjs_hw_gpio_read(int pin)
220	{
221	  if (!qjs_hw_gpio_valid(pin))
222	    {
223	      return -EINVAL;
224	    }
225	
226	  return esp32s3_gpioread(pin) ? 1 : 0;
227	}
228	
229	int qjs_hw_gpio_toggle(int pin)
230	{
231	  int v;
232	
233	  v = qjs_hw_gpio_read(pin);
234	  if (v < 0)
235	    {
236	      return v;
237	    }
238	
239	  return qjs_hw_gpio_write(pin, !v);
240	}
