242	/****************************************************************************
243	 * WS2812 via RMT (official NuttX / ESP HAL path)
244	 ****************************************************************************/
245	
246	#if defined(CONFIG_ESP_RMT)
247	
248	/* One RGB LED is 24 RMT symbols + 1 stop. ESP32-S3 has 48 words/channel.
249	 * The official /dev/leds0 path always transmits CONFIG_WS2812_LED_COUNT
250	 * (was 8 → 193 symbols) and then waits forever for TX_END. The first 48
251	 * words go out (LED latches red = hue 0) and qjs hangs. Drive RMT
252	 * ourselves with a single-block transfer.
253	 */
254	
255	#define QJS_HW_WS2812_T0H   28u   /* 0.35us @ 80MHz / div1 */
256	#define QJS_HW_WS2812_T0L   72u   /* 0.90us */
257	#define QJS_HW_WS2812_T1H   72u   /* 0.90us */
258	#define QJS_HW_WS2812_T1L   28u   /* 0.35us */
259	#define QJS_HW_WS2812_BITS  24
260	#define QJS_HW_WS2812_SYMS  (QJS_HW_WS2812_BITS + 1)
261	
262	struct rmt_dev_s *esp_rmt_tx_init(int ch, int pin);
263	
264	static struct rmt_dev_s *g_ws_rmt;
265	static int g_ws_pin = -1;
266	
267	static uint32_t ws2812_symbol(int one)
268	{
269	  if (one)
270	    {
271	      return (QJS_HW_WS2812_T1L << 16) | 0x8000u | QJS_HW_WS2812_T1H;
272	    }
273	
274	  return (QJS_HW_WS2812_T0L << 16) | 0x8000u | QJS_HW_WS2812_T0H;
275	}
276	
277	static void ws2812_encode_byte(uint32_t *dst, uint8_t byte)
278	{
279	  int i;
280	
281	  for (i = 7; i >= 0; i--)
282	    {
283	      *dst++ = ws2812_symbol((byte >> i) & 1);
284	    }
285	}
286	
287	static int qjs_hw_ws2812_ensure(int pin)
288	{
289	  if (g_ws_rmt != NULL)
290	    {
291	      return (pin == g_ws_pin) ? OK : -EBUSY;
292	    }
293	
